    // Lookup returns the Info with the given name.
    Info* Lookup(gocpp::string name)
    {
        // binary search, avoiding import of sort.
        auto lo = 0;
        auto hi = len(All);
        for(; lo < hi; )
        {
            auto m = int((unsigned int)(lo + hi) >> 1);
            auto mid = All[m].Name;
            if(name == mid)
            {
                return & All[m];
            }
            if(name < mid)
            {
                hi = m;
            }
            else
            {
                lo = m + 1;
            }
        }
        return nullptr;
    }

